// Local workbench v2: events, reusable workflows, contribution ledger and shared schedule.
let sopDocuments=[],sopLoading=false,calendarDept='',timelineScale=68,selectedDay='';
const canEditEvent=e=>!!e&&(admin()||manager()&&e.createdBy===user.id);
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dayShift=(s,n)=>{const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const dayDiff=(a,b)=>Math.round((Date.parse(a.slice(0,10))-Date.parse(b.slice(0,10)))/86400000);
const externalLink=(url,label,extra='')=>url?`<a class="secondary link-button" href="${esc(url)}" target="_blank" rel="noopener noreferrer" ${extra}>${esc(label)} ↗</a>`:'';
const eventTime=e=>`${dateText(e.date)}${e.allDay===false?' '+esc(e.startTime):' · 全天'}${e.endDate&&e.endDate!==e.date?' — '+dateText(e.endDate):''}${e.allDay===false?' — '+esc(e.endTime):''}`;
const visibleEvents=()=>state.events.filter(e=>!calendarDept||e.department===calendarDept||state.tasks.some(t=>t.event===e.id&&(t.depts||[t.dept]).includes(calendarDept)));
const visibleTasks=()=>state.tasks.filter(t=>!calendarDept||(t.depts||[t.dept]).includes(calendarDept));
function rewardFields(value={}) {return `<div class="form-grid"><label class="field">每项任务积分<input name="rewardPoints" type="number" min="0" max="10000" step="1" value="${Number(value.rewardPoints||0)}"></label><label class="field">其他奖励备注<input name="rewardNote" maxlength="500" value="${esc(value.rewardNote||'')}" placeholder="如：优秀作品展示、实践证明"></label></div><p class="sub">任务验收通过后积分入账一次。活动中的设置用于新任务，已有任务可在调整分工中修改。</p>`}

// Keep open forms intact while refreshing data; mutations and sibling tabs refresh immediately.
const baseApi=api;
let refreshSerial=0;
const baseRender=render,timelinePositions=new Map();
render=function(){
  const previous=$('.time-scroll');if(previous)timelinePositions.set(previous.dataset.month,previous.scrollLeft);
  baseRender();const scroll=$('.time-scroll');if(scroll){const key=`${year}-${month}`;scroll.dataset.month=key;scroll.scrollLeft=timelinePositions.get(key)??(year===new Date().getFullYear()&&month===new Date().getMonth()?Math.max(0,new Date().getDate()-3)*timelineScale:0)}
};
const baseAuth=auth;
auth=function(...args){baseAuth(...args);const mark=$('.auth-brand .mark');if(mark)mark.outerHTML='<img class="brand-wordmark" src="/brand/wordmark.png" alt="冯如书院 FENGRU COLLEGE">'};
refresh=async function(){
  const serial=++refreshSerial,next=await api('state');
  const nextMembers=view==='members'?(await api('members')).members:members;
  if(serial!==refreshSerial)return;
  state=next;user=state.user;members=nextMembers;render();maybeStartTour();
};
const syncChannel=typeof BroadcastChannel==='function'?new BroadcastChannel('fengru-workbench-v2'):null;
if(syncChannel)syncChannel.onmessage=()=>{if(user?.status==='active')refresh().catch(()=>{})};
api=async function(path,data){const result=await baseApi(path,data);if(data&&user?.status==='active'&&!['login','logout','register','setup','recover'].includes(path)){syncChannel?.postMessage('changed');await refresh()}return result};

const oldOverview=overview;
overview=function(){const body=oldOverview();const pos=body.indexOf('<div class="overview-grid">');return body.slice(0,pos)+timelineView()+body.slice(pos)};

function eventFields(e={}){
  const day=e.date||localDay();
  return `<label class="field">活动名称<input name="name" required maxlength="60" value="${esc(e.name||'')}" placeholder="添加活动标题"></label>
    <label class="check-line"><input type="checkbox" name="allDay" ${e.allDay!==false?'checked':''}> 全天</label>
    <div class="form-grid"><label class="field">开始日期<input type="date" name="date" required value="${day}"></label><label class="field">结束日期<input type="date" name="endDate" required value="${e.endDate||day}"></label></div>
    <div class="form-grid time-fields" ${e.allDay!==false?'hidden':''}><label class="field">开始时间<input type="time" name="startTime" value="${e.startTime||'09:00'}"></label><label class="field">结束时间<input type="time" name="endTime" value="${e.endTime||'10:00'}"></label></div>
    <label class="field">地点（可选）<input name="location" maxlength="100" value="${esc(e.location||'')}" placeholder="添加地点或线上会议位置"></label>
    <div class="form-grid"><label class="field">需求来源<select name="source">${options(['学媒自有','外派需求'],e.source||'学媒自有')}</select></label><label class="field">需求方 / 对接人（可选）${requesterField(e.requester||'')}</label></div>
    <label class="field">活动说明与交付目标<textarea name="description" maxlength="3000" placeholder="安排、参与范围、期望成果和注意事项">${esc(e.description||'')}</textarea></label>
    <label class="field">活动素材库 · 云盘上传链接（可稍后添加）<input type="url" name="cloudUrl" maxlength="2000" value="${esc(e.cloudUrl||'')}" placeholder="https://…"></label>
    <p class="sub">请提供成员有上传权限的文件夹链接；接活人会在任务详情和提交页面看到入口。</p>
    <details class="form-section" ${e.rewardPoints||e.rewardNote?'open':''}><summary>积分与其他奖励</summary>${rewardFields(e)}</details>`;
}
createForm=function(template='blank'){
  modal('新建活动',`<form id="create-form"><label class="field">活动模板<select name="template"><option value="blank">空白日程</option>${(state.templates||[]).map(t=>`<option value="${t.id}" ${template===t.id?'selected':''}>${esc(t.name)} · ${t.steps.length} 个环节</option>`).join('')}</select></label>${eventFields()}<div id="template-assignment"></div></form>`,`<button class="primary" type="submit" form="create-form">创建活动</button>`);
  renderAssignments();
};
function renderAssignments(){
  const template=(state.templates||[]).find(t=>t.id===$('#create-form [name=template]').value);
  $('#template-assignment').innerHTML=template?`<h3 class="detail-label">确认任务分工</h3><p class="sub">${esc(template.description||'')} 模板会复制为本活动任务，后续修改模板不会改动已创建活动。</p>${template.steps.map((s,i)=>`<fieldset class="assignment" data-assignment="${i}"><legend>${i+1}. ${esc(s.name)}</legend><p class="sub">${esc(s.dept)} · 活动${s.offset<0?'前':'后'} ${Math.abs(s.offset)} 天 ${s.time}</p><div class="form-grid"><label class="field">负责人<select name="owner-${i}" required><option value="">请选择</option>${peopleOptions(state.people.find(p=>p.dept===s.dept)?.id)}</select></label><label class="field">验收人<select name="receiver-${i}">${peopleOptions(user.id)}</select></label></div></fieldset>`).join('')}`:'<div class="hint">只创建日程，不自动派单。创建后可按需添加任务，也可将活动流程保存成模板。</div>';
}
function eventPayload(f){const d=Object.fromEntries(new FormData(f));return {...d,allDay:f.elements.allDay.checked,assignments:[...f.querySelectorAll('[data-assignment]')].map(el=>({owner:el.querySelector('[name^=owner-]').value,receiver:el.querySelector('[name^=receiver-]').value}))}}
function editEvent(id){const e=state.events.find(x=>x.id===id);modal('编辑活动',`<form id="event-edit-form" data-id="${id}">${eventFields(e)}<p class="hint">调整开始日期时，未完成任务同步平移；已完成任务和已发积分保留。</p></form>`,`<button class="primary" type="submit" form="event-edit-form">保存活动</button>`)}
function addTaskForm(id){const e=state.events.find(x=>x.id===id),ts=state.tasks.filter(t=>t.event===id);modal('添加活动任务',`<form id="task-new-form" data-event="${id}"><p class="sub">${esc(e.name)}</p><label class="field">任务名称<input name="name" required maxlength="100"></label><div class="form-grid"><label class="field">负责人<select name="owner">${peopleOptions(user.id)}</select></label><label class="field">验收人<select name="receiver">${peopleOptions(user.id)}</select></label></div><label class="field">截止时间<input name="due" type="datetime-local" value="${e.date}T${e.endTime||'18:00'}" required></label><label class="field">交付要求<textarea name="requirements" required maxlength="3000" placeholder="明确交付物、验收标准和交接说明"></textarea></label><details class="form-section"><summary>前序依赖（可选）</summary><p class="sub">所选任务全部验收后，才可以接受此任务。</p>${ts.map(t=>`<label class="check-line"><input type="checkbox" name="depends" value="${t.id}">${esc(t.name)}</label>`).join('')||'<p class="sub">当前还没有前序任务</p>'}</details>${rewardFields(e)}</form>`,`<button class="primary" form="task-new-form" type="submit">添加并派单</button>`)}
function cloudBlock(e){return e.cloudUrl?`<div class="cloud-card"><div><h3>活动素材库</h3><p class="sub">上传到活动统一文件夹，便于跨部门交接。</p></div><div class="actions">${externalLink(e.cloudUrl,'打开云盘上传')}<button type="button" class="text-btn" data-copy-url="${esc(e.cloudUrl)}">复制链接</button></div></div>`:'<p class="sub">暂未设置活动素材库，可由活动负责人稍后补充。</p>'}
function showEvent(id){const e=state.events.find(x=>x.id===id);if(!e)return;const ts=state.tasks.filter(t=>t.event===id);modal(e.name,`<p class="event-kicker">${esc(e.type||'自由活动')} · ${esc(e.source||'学媒自有')}</p><h3>${eventTime(e)}</h3><p class="sub">${esc(e.location||'地点待定')}${e.requester?' · 对接：'+esc(e.requester):''}</p><p class="detail-copy">${esc(e.description||'暂无补充说明')}</p>${cloudBlock(e)}<p class="reward-label">新任务默认 ${e.rewardPoints||0} 积分${e.rewardNote?' · '+esc(e.rewardNote):''}</p><h3 class="detail-label">任务与交付</h3>${ts.map(taskRow).join('')||'<div class="empty">还没有任务，可以保留为日程或稍后添加分工。</div>'}`,canEditEvent(e)?`<button class="secondary" data-from-event="${id}">保存为模板</button><button class="secondary" data-event-edit="${id}">编辑活动</button><button class="primary" data-add-task="${id}">＋ 添加任务</button>${admin()?`<button class="danger" data-event-delete="${id}">删除活动</button>`:''}`:'')}
activitiesView=function(){return head('所有任务','',manager()?'<button class="primary" data-create>＋ 新建活动</button>':'')+state.events.map(e=>{const ts=state.tasks.filter(t=>t.event===e.id);return `<section class="activity-card"><div class="activity-top"><div class="activity-title"><span class="event-kicker">${esc(e.type||'自由活动')} · ${esc(e.source||'学媒自有')}</span><h2><button class="title-button" data-event="${e.id}">${esc(e.name)}</button></h2><p>${eventTime(e)} · ${esc(e.location||'地点待定')}</p></div><div class="actions"><button class="secondary" data-event="${e.id}">活动详情</button>${canEditEvent(e)?`<button class="primary" data-add-task="${e.id}">＋ 任务</button>`:''}</div></div>${e.description?`<p class="detail-copy">${esc(e.description)}</p>`:''}${cloudBlock(e)}<div class="activity-progress"><span>${ts.filter(t=>t.status==='done').length} / ${ts.length} 项任务完成</span><span>任务奖励共 ${ts.reduce((n,t)=>n+(t.rewardPoints||0),0)} 积分</span></div><div class="flow">${ts.map((t,i)=>`<div class="flow-step" role="button" tabindex="0" data-task="${t.id}"><div class="step-num">${String(i+1).padStart(2,'0')} / ${esc(t.dept)}</div><h3>${esc(t.name)}</h3>${badge(t)}<p>${esc(person(t.owner))}</p><p>${dateText(t.due)}</p><span class="reward-label">+${t.rewardPoints||0} 积分</span></div>`).join('')}</div>${!ts.length?'<p class="sub">空白日程 · 尚未派单</p>':''}</section>`}).join('')+(!state.events.length?'<div class="panel empty">还没有活动。点击“新建活动”添加一个空白日程。</div>':'')};

const baseShowTask=showTask;
showTask=function(id){baseShowTask(id);const t=state.tasks.find(x=>x.id===id);if(!t)return;const e=ev(t);const content=$('#dialog .modal-content');content.insertAdjacentHTML('beforeend',`${cloudBlock(e)}<div class="reward-label">本任务 ${t.rewardPoints||0} 积分${t.rewardNote?' · '+esc(t.rewardNote):''}${t.status==='done'?' · 已验收入账':''}</div>${t.uploadReceipt?`<div class="hint">提交者已确认上传（${dateText(t.uploadReceipt.confirmedAt.slice(0,16))}）。${externalLink(t.uploadReceipt.url,'查看提交时的上传位置')}<p>此记录为成员确认，验收人仍需检查云盘内的实际文件。</p></div>`:''}`);if(t.owner===user.id&&t.status==='conflict'){$('#dialog-body').insertAdjacentHTML('beforeend',`<div class="modal-footer"><button class="primary" data-action="resume" data-id="${id}">冲突已解决，恢复接活</button></div>`)}};
function checkInformation(t,i){const e=ev(t);return i===0?`${e.name}\n时间：${eventTime(e).replace(/<[^>]+>/g,'')}\n地点：${e.location||'待定'}\n活动说明：${e.description||'无'}\n交付要求：${t.requirements}\n截止：${dateText(t.due)}\n验收人：${person(t.receiver)}`:`交接给：${person(t.receiver)}\n写清已完成内容、文件位置、版本及待注意事项。\n文件命名：日期_活动名_内容_序号。\n照片按场景分类并记录摄影署名；视频按机位/环节归类；设计保留可编辑源文件与导出图。\n${e.cloudUrl?'上传到本活动素材库，并确认接收人可访问。':'可附个人成果链接，并确认接收人可访问。'}`}
submitForm=function(id){const t=state.tasks.find(x=>x.id===id),e=ev(t);modal('提交成果',`<form id="submit-form" data-id="${id}" data-upload-url="${esc(e.cloudUrl||'')}"><div class="checklist">${t.checks.map((c,i)=>`<div class="check-detail"><label class="check-line"><input type="checkbox" name="check${i}" required><span>${esc(c)}</span></label><details class="check-help"><summary title="${esc(checkInformation(t,i))}">查看要求</summary><div class="check-popover">${esc(checkInformation(t,i))}</div></details></div>`).join('')}</div><label class="field" style="margin-top:20px">成果与交接说明<textarea name="submission" required maxlength="3000" placeholder="完成了什么、文件在哪里、有哪些交接事项">${esc(t.submission||'')}</textarea></label>${e.cloudUrl?`<section class="upload-section"><h3>上传到活动素材库</h3><p class="sub">先打开云盘完成上传，再返回确认。此处不会自动上传文件或验证云盘内容。</p>${externalLink(e.cloudUrl,'前往云盘上传','data-open-upload')}<label class="check-line"><input type="checkbox" name="uploadConfirmed" required disabled> 我已完成上传，并确认验收人能访问文件</label></section>`:''}<label class="field">个人成果链接（可选）<input name="link" type="url" maxlength="2000" value="${esc(t.link||'')}" placeholder="https://…"></label><div class="personal-link-confirm" ${t.link?'':'hidden'}><button type="button" class="secondary" data-preview-link>打开链接核对 ↗</button><label class="check-line"><input type="checkbox" name="linkConfirmed" ${t.link?'required':''}> 我已核对链接和访问权限</label></div></form>`,`<button class="primary" form="submit-form" type="submit">提交给 ${esc(person(t.receiver))}</button>`)};

function templatesView(){return head('流程模板','',manager()?'<button class="primary" data-template-new>＋ 创建模板</button>':'')+`<div class="template-grid"><section class="template-card blank-template"><span class="event-kicker">自由安排</span><h2>空白日程</h2><p>填写活动信息后，可添加任务。</p>${manager()?'<button class="secondary" data-create>新建日程</button>':''}</section>${(state.templates||[]).map(t=>`<section class="template-card"><span class="event-kicker">${t.createdBy?'团队模板':'SOP 标准流程'} · ${t.steps.length} 个环节</span><h2>${esc(t.name)}</h2><p>${esc(t.description||'')}</p><ol>${t.steps.map(s=>`<li>${esc(s.name)} <small>${esc(s.dept)}</small></li>`).join('')}</ol>${manager()?`<div class="actions"><button class="primary" data-use-template="${t.id}">使用模板</button><button class="secondary" data-template-edit="${t.id}">${t.createdBy&&(admin()||t.createdBy===user.id)?'编辑':'复制编辑'}</button></div>`:''}</section>`).join('')}</div>`}
function stepEditor(s={},i=0){return `<fieldset class="template-step"><legend>环节 <span class="step-index">${i+1}</span></legend><label class="field">环节名称<input data-key="name" required maxlength="100" value="${esc(s.name||'')}"></label><div class="form-grid"><label class="field">建议部门<select data-key="dept">${options(depts,s.dept||user.dept)}</select></label><label class="field">距活动开始日（天）<input data-key="offset" type="number" min="-365" max="365" value="${s.offset||0}" required></label></div><div class="form-grid"><label class="field">截止时间<input data-key="time" type="time" value="${s.time||'18:00'}" required></label><label class="field">前序环节编号<input data-key="depends" value="${(s.depends||[]).map(j=>j+1).join(',')}" placeholder="如：1,2；无依赖则留空"></label></div><label class="field">交付要求<textarea data-key="requirements" maxlength="3000" required>${esc(s.requirements||'')}</textarea></label><div class="form-grid"><label class="field">积分（留空沿用活动设置）<input data-key="rewardPoints" type="number" min="0" max="10000" value="${s.rewardPoints??''}"></label><label class="field">其他奖励<input data-key="rewardNote" maxlength="500" value="${esc(s.rewardNote||'')}"></label></div><button type="button" class="text-btn danger-text" data-remove-step>删除此环节</button></fieldset>`}
function templateForm(id,preset){const original=(state.templates||[]).find(t=>t.id===id);const editable=original?.createdBy&&(admin()||original.createdBy===user.id);const t=preset||original||{};modal(editable?'编辑模板':'创建模板',`<form id="template-form" data-id="${editable?id:''}"><label class="field">模板名称<input name="name" value="${esc(t.name||'')}" required maxlength="60"></label><label class="field">使用说明<textarea name="description" maxlength="500">${esc(t.description||'')}</textarea></label><div id="template-steps">${(t.steps||[]).map(stepEditor).join('')}</div><button class="secondary" type="button" data-add-step>＋ 添加环节</button><p class="sub">用相对活动开始日的天数表示排期（负数为提前）。前序编号必须小于当前环节；保存后可在新建活动中选择。</p></form>`,`<button class="primary" form="template-form" type="submit">保存模板</button>`)}
function templatePayload(f){const d=Object.fromEntries(new FormData(f));return {...d,...(f.dataset.id?{id:f.dataset.id}:{}),steps:[...f.querySelectorAll('.template-step')].map(el=>{const x=Object.fromEntries([...el.querySelectorAll('[data-key]')].map(n=>[n.dataset.key,n.value]));return {...x,offset:Number(x.offset),rewardPoints:x.rewardPoints===''?null:Number(x.rewardPoints),depends:x.depends.trim()?x.depends.split(/[,，]/).map(v=>Number(v.trim())-1):[]}})}}
function templateFromEvent(id){const e=state.events.find(x=>x.id===id),ts=state.tasks.filter(t=>t.event===id);templateForm(null,{name:e.name+'流程',description:e.description||'',steps:ts.map(t=>({name:t.name,dept:t.dept,offset:dayDiff(t.due,e.date),time:t.due.slice(11,16),depends:t.depends.map(id=>ts.findIndex(x=>x.id===id)),requirements:t.requirements,rewardPoints:t.rewardPoints,rewardNote:t.rewardNote}))})}
function rewardRanking(){const totals={};state.ledger.forEach(x=>{if(x.points)totals[x.user]=(totals[x.user]||0)+x.points});const rows=Object.entries(totals).map(([id,points])=>({name:person(id)||'已停用成员',points,me:id===user.id})).sort((a,b)=>b.points-a.points).slice(0,10);const medals=['🥇','🥈','🥉'];const max=Math.max(1,...rows.map(x=>x.points));return `<section class="panel"><div class="panel-head"><h2>积分排名</h2></div><div class="rank-list">${rows.map((r,i)=>`<div class="rank-row ${r.me?'me':''}"><span class="rank-medal">${medals[i]||(i+1)}</span><div class="rank-copy"><b>${esc(r.name)}</b><span class="rank-bar"><i style="width:${Math.max(2,Math.round(r.points/max*100))}%"></i></span></div><strong>${r.points}分</strong></div>`).join('')||'<div class="empty">暂无积分记录</div>'}</div></section>`}
function rewardsView(){const ledger=state.ledger||[],mine=ledger.filter(x=>x.user===user.id),total=mine.reduce((n,x)=>n+x.points,0);return head('贡献与积分','')+`<div class="reward-summary"><div><span class="event-kicker">我的累计积分</span><strong>${total}<small>分</small></strong></div><div><h3>${mine.length} 项任务已验收</h3><p class="sub">任务验收后计入积分；其他奖励按备注兑现。</p></div></div>${rewardRanking()}<section class="panel"><div class="panel-head"><h2>${admin()?'全体成员':manager()?'本部门':'我的'}积分记录</h2></div>${[...ledger].reverse().map(x=>`<div class="asset-row"><span class="points-chip">+${x.points}</span><div class="task-copy"><h3>${esc(x.taskName)}</h3><p>${esc(x.eventName)} · ${esc(person(x.user))} · 验收人 ${esc(person(x.approvedBy))}</p>${x.note?`<p>奖励备注：${esc(x.note)}</p>`:''}</div><small>${dateText(x.time.slice(0,16))}</small></div>`).join('')||'<div class="empty">暂无积分记录</div>'}</section>`}

function scheduleToolbar(){return `<div class="schedule-controls"><div class="actions"><button class="secondary" data-month="-1" aria-label="上月">‹</button><h2>${year} 年 ${month+1} 月</h2><button class="secondary" data-month="1" aria-label="下月">›</button><button class="text-btn" data-today>今天</button></div><label class="filter-label">部门<select data-calendar-dept><option value="">所有可见部门</option>${options(depts,calendarDept)}</select></label></div>`}
function timelineView(){const first=`${year}-${String(month+1).padStart(2,'0')}-01`,days=new Date(year,month+1,0).getDate(),events=visibleEvents().filter(e=>e.date<=dayShift(first,days-1)&&(e.endDate||e.date)>=first);return `<section class="panel schedule-panel"><div class="panel-head"><div><span class="event-kicker">共享排期</span><h2>活动时间轴</h2></div><button class="text-btn" data-view="calendar">查看日历 →</button></div>${scheduleToolbar()}<div class="timeline-tools"><span class="sub">横向拖动浏览 · 点击活动查看 · 拖动 ⠿ 调整日期</span><label>缩放 <input type="range" min="44" max="110" value="${timelineScale}" data-timeline-scale aria-label="时间轴缩放"></label></div><div class="time-scroll" tabindex="0" aria-label="活动时间轴，可横向滚动"><div class="time-canvas" style="--day-width:${timelineScale}px;width:${days*timelineScale}px"><div class="time-dates">${Array.from({length:days},(_,i)=>{const d=dayShift(first,i);return `<button class="time-date ${d===localDay()?'today':''} ${d===selectedDay?'selected':''}" style="width:${timelineScale}px" data-select-day="${d}">${i+1}<small>${['日','一','二','三','四','五','六'][new Date(d+'T12:00').getDay()]}</small></button>`}).join('')}</div>${events.map(e=>{const start=Math.max(0,dayDiff(e.date,first)),end=Math.min(days,dayDiff(e.endDate||e.date,first)+1);return `<div class="time-lane"><div class="time-bar" style="left:${start*timelineScale+3}px;width:${Math.max(timelineScale-6,(end-start)*timelineScale-6)}px" title="${esc(e.name)} · ${esc(eventTime(e))}">${canEditEvent(e)?`<button class="drag-handle" data-drag-event="${e.id}" title="拖动调整日期，也可在活动详情编辑" aria-label="拖动调整 ${esc(e.name)} 日期">⠿</button>`:''}<button class="time-event" data-event="${e.id}">${esc(e.name)}</button></div></div>`}).join('')||'<div class="timeline-empty">本月暂无活动，可切换月份或新建日程。</div>'}</div></div>${selectedDay?`<div class="selected-day"><h3>${dateText(selectedDay)}</h3>${visibleTasks().filter(t=>t.due.startsWith(selectedDay)).map(taskRow).join('')||'<p class="sub">当日暂无任务截止。</p>'}</div>`:''}</section>`}
calendarView=function(){const start=(new Date(year,month,1).getDay()+6)%7,last=new Date(year,month+1,0).getDate();let cells='';for(let i=0;i<Math.ceil((start+last)/7)*7;i++){const d=i-start+1,key=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells+=`<div class="day ${d<1||d>last?'out':''} ${key===localDay()?'today':''} ${key===selectedDay?'selected':''}">${d<1||d>last?'':`<button class="day-num" data-select-day="${key}">${d}</button>${visibleEvents().filter(e=>e.date<=key&&(e.endDate||e.date)>=key).map(e=>`<button class="cal-event activity" data-event="${e.id}" title="${esc(e.name)}">${esc(e.name)}</button>`).join('')}${visibleTasks().filter(t=>t.due.startsWith(key)).map(t=>`<button class="cal-event" data-task="${t.id}" title="${esc(t.name)}">${t.due.slice(11)} ${esc(t.name)}</button>`).join('')}`}</div>`}return head('日历与时间轴','活动日期与任务截止时间共用同一份排期。',manager()?'<button class="primary" data-create>＋ 新建活动</button>':'')+`<div class="calendar">${scheduleToolbar()}<div class="cal-week">${['一','二','三','四','五','六','日'].map(x=>`<div>周${x}</div>`).join('')}</div><div class="cal-grid">${cells}</div></div>`+timelineView()};

function adminStatsView(){loadAdminStats().then(s=>{if(view==='stats'&&s)renderAdminStats(s)}).catch(()=>{if(view==='stats')document.getElementById('admin-stats').innerHTML='<div class="empty">统计暂时无法读取</div>'});return head('站长统计','这里汇总网站访问数据，方便了解使用情况。')+`<div id="admin-stats"><div class="empty">正在读取统计…</div></div>`}
function loadAdminStats(){return api('stats')}
function renderAdminStats(s){const total=s.total||0,days=s.days||[],max=Math.max(1,...days.map(d=>d.hits));const bars=days.slice().reverse().map(d=>`<div class="stat-bar-item"><div class="stat-bar" style="height:${Math.round(d.hits/max*100)}%"></div><span>${d.date.slice(5)}</span><b>${d.hits}</b></div>`).join('');document.getElementById('admin-stats').innerHTML=`<div class="stat-total">累计访问 <strong>${total}</strong> 次</div><div class="stat-chart">${bars||'<div class="empty">暂无访问数据</div>'}</div>`}
function sopView(){if(!sopDocuments.length&&!sopLoading){sopLoading=true;fetch('/sop-docs.json').then(r=>r.json()).then(x=>{sopDocuments=x;if(view==='sop')render()}).catch(()=>toast('SOP 文档暂时无法读取')).finally(()=>sopLoading=false)}return head('知识库','')+`<div class="sop-principles"><div><b>01 / 一个入口</b><p>外派需求先由办公室登记，明确来源、交付目标、负责人和验收人。</p></div><div><b>02 / 素材先行</b><p>文案提前预写；照片精选交付后，再完成推送排版。任务前序验收后自动解锁。</p></div><div><b>03 / 验收与归档</b><p>统一活动素材库，保留成果链接与交接记录；成熟流程保存为模板，供下次复用。</p></div></div><div class="hint">照片精选按素材库细则在活动后 48 小时内交付，视频素材按 72 小时执行；实际截止时间以负责人在任务中确认的排期为准。</div><section class="panel"><div class="panel-head"><h2>部门手册与规范</h2><button class="text-btn" data-sop-tour>边看边点 · 新手引导</button></div>${sopDocuments.map((d,i)=>`<button class="sop-document" data-sop-doc="${i+1}"><span>${esc(d.title)}</span><small>${esc(d.path)}</small><span>阅读 ↗</span></button>`).join('')||'<div class="empty">正在读取本地知识库…</div>'}</section><p class="sub">点开即可全屏阅读；《新手快速入门》带步骤勾选和「边看边点」按键引导。</p>`}
function sopImageUrl(url){if(/^https?:\/\//i.test(url))return url;if(url.startsWith('/guide/'))return url;const file=url.replace(/^screenshots\//,'').split('/').pop();return '/guide/'+encodeURIComponent(file)}
function sopFigure(alt,url){return `<figure><img class="guide-screenshot" src="${esc(sopImageUrl(url))}" alt="${esc(alt)}" loading="lazy"><figcaption>${esc(alt)}</figcaption></figure>`}
function sopMarkdown(src){
 const lines=String(src||'').replace(/\r\n/g,'\n').split('\n');let html='',i=0;
 const inline=s=>esc(s)
  .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
  .replace(/`([^`]+)`/g,'<code>$1</code>')
  .replace(/!\[([^\]]*)\]\(([^)]+)\)/g,(m,alt,url)=>`<img class="guide-screenshot" src="${esc(sopImageUrl(url))}" alt="${esc(alt)}" loading="lazy">`)
  .replace(/\[([^\]]+)\]\(([^)]+)\)/g,(m,label,url)=>{const v=url.match(/^view:(.+)$/);if(v)return `<button type="button" class="text-btn sop-jump" data-sop-nav="${esc(v[1])}">${label}</button>`;return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`});
 while(i<lines.length){
  const line=lines[i];if(!line.trim()){i++;continue}
  if(line.startsWith('@@sandbox ')){const type=line.slice(9).trim();if(/^[a-z]+$/.test(type)){html+=`<div class="sop-sandbox" data-sandbox="${esc(type)}"></div>`;i++;continue}}
  if(line.startsWith('```')){let code='';i++;while(i<lines.length&&!lines[i].startsWith('```')){code+=(code?'\n':'')+lines[i];i++}i++;html+='<pre><code>'+esc(code)+'</code></pre>';continue}
  let m;
  if(m=line.match(/^!\[([^\]]*)\]\(([^)]+)\)\s*$/)){html+=sopFigure(m[1],m[2]);i++;continue}
  if(m=line.match(/^######\s+(.*)$/)){html+='<h6>'+inline(m[1])+'</h6>';i++;continue}
  if(m=line.match(/^#####\s+(.*)$/)){html+='<h5>'+inline(m[1])+'</h5>';i++;continue}
  if(m=line.match(/^####\s+(.*)$/)){html+='<h4>'+inline(m[1])+'</h4>';i++;continue}
  if(m=line.match(/^###\s+(.*)$/)){html+='<h3>'+inline(m[1])+'</h3>';i++;continue}
  if(m=line.match(/^##\s+(.*)$/)){html+='<h2>'+inline(m[1])+'</h2>';i++;continue}
  if(m=line.match(/^#\s+(.*)$/)){html+='<h1>'+inline(m[1])+'</h1>';i++;continue}
  if(line.startsWith('|')){const rows=[];while(i<lines.length&&lines[i].startsWith('|')){rows.push(lines[i]);i++}if(rows.length>=2&&/^[\s|:-]+$/.test(rows[1].replace(/\|/g,''))){const parseRow=r=>r.replace(/^\|/,'').replace(/\|$/,'').split('|').map(c=>inline(c.trim()));const header=parseRow(rows[0]);let body='';for(let r=2;r<rows.length;r++){body+='<tr>'+parseRow(rows[r]).map(c=>'<td>'+c+'</td>').join('')+'</tr>'}html+='<table><thead><tr>'+header.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+body+'</tbody></table>';continue}}
  if(m=line.match(/^\s*[-*]\s+\[([ xX])\]\s+(.*)$/)){const items=[];while(i<lines.length&&(m=lines[i].match(/^\s*[-*]\s+\[([ xX])\]\s+(.*)$/))){items.push(`<li class="sop-step"><label><input type="checkbox" data-sop-check> ${inline(m[2])}</label></li>`);i++}html+='<ul class="sop-checklist">'+items.join('')+'</ul>';continue}
  if(/^[-*]\s+/.test(line)){const items=[];while(i<lines.length&&/^[-*]\s+/.test(lines[i])){items.push('<li>'+inline(lines[i].replace(/^[-*]\s+/,''))+'</li>');i++}html+='<ul>'+items.join('')+'</ul>';continue}
  if(/^\d+\.\s+/.test(line)){const items=[];while(i<lines.length&&/^\d+\.\s+/.test(lines[i])){items.push('<li>'+inline(lines[i].replace(/^\d+\.\s+/,''))+'</li>');i++}html+='<ol>'+items.join('')+'</ol>';continue}
  if(line.startsWith('> ')){const items=[];while(i<lines.length&&lines[i].startsWith('> ')){items.push(inline(lines[i].slice(2)));i++}html+='<blockquote>'+items.join('<br>')+'</blockquote>';continue}
  const p=[];while(i<lines.length&&lines[i].trim()&&!/^(#{1,6}\s+|\||```|[-*]\s+|\d+\.\s+|>\s+|!\[)/.test(lines[i])){p.push(inline(lines[i]));i++}html+='<p>'+p.join('<br>')+'</p>'
 }
 return html
}
const SOP_PROGRESS_KEY='fengru-sop-progress';
const SOP_FONT_KEY='fengru-sop-font';
const SOP_SEEN_KEY='fengru-tour-done';
function sopProgressStore(){try{return JSON.parse(localStorage.getItem(SOP_PROGRESS_KEY)||'{}')}catch{return{}}}
function sopProgressPath(key){const i=key.lastIndexOf('#');return i>0?key.slice(0,i):key}
function sopFontScale(){const v=parseFloat(localStorage.getItem(SOP_FONT_KEY)||'1');return Number.isFinite(v)&&v>=0.85&&v<=1.5?v:1}
function applySopFont(scope){const reader=scope?.querySelector?.('.sop-reader');if(reader)reader.style.fontSize=Math.round(15*sopFontScale())+'px'}
function adjustSopFont(delta){const cur=sopFontScale(),next=Math.max(0.85,Math.min(1.5,Math.round((cur+delta)*10)/10));try{localStorage.setItem(SOP_FONT_KEY,String(next))}catch{};applySopFont(document.getElementById('sop-fullscreen'))}
function sopProgressRender(scope,path){const checks=[...(scope?.querySelectorAll?.('[data-sop-check]')||[])];const total=checks.length,done=checks.filter(c=>c.checked).length;const label=scope.querySelector('[data-sop-progress-label]'),fill=scope.querySelector('[data-sop-progress-fill]');if(label)label.textContent=`${done} / ${total}`;if(fill)fill.style.width=(total?Math.round(done/total*100):0)+'%';if(path){const store=sopProgressStore();store[path]=checks.map((c,i)=>c.checked?i:-1).filter(i=>i>=0);try{localStorage.setItem(SOP_PROGRESS_KEY,JSON.stringify(store))}catch{}}}
function sopChecklistInit(scope,path){const saved=sopProgressStore()[path]||[];const checks=[...(scope.querySelectorAll('[data-sop-check]'))];checks.forEach((c,i)=>{c.dataset.sopCheck=path+'#'+i;c.checked=saved.includes(i)});sopProgressRender(scope,path)}
function completeSandbox(host){const scope=host.closest('#sop-fullscreen');if(!scope)return;let next=null;for(const c of scope.querySelectorAll('[data-sop-check]')){if(host.compareDocumentPosition(c)&Node.DOCUMENT_POSITION_FOLLOWING){next=c;break}}if(next&&!next.checked){next.checked=true;next.dispatchEvent(new Event('change',{bubbles:true}))}}
function sandboxDone(host,html){host.classList.add('done');host.insertAdjacentHTML('beforeend',`<div class="sop-sandbox-ok">${html}</div>`)}
function sandboxLogin(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="auth-card sop-sandbox-card"><div class="eyebrow">FENGRU · MEDIA CENTER</div><h1>账号登录</h1><form novalidate><label class="field">用户名<input name="username" autocomplete="off" placeholder="3—32 位英文、数字或 . _ -"></label><label class="field">密码<input name="password" type="password" autocomplete="new-password" placeholder="至少 10 个字符"></label><label class="check-line"><input type="checkbox" name="remember"> 记住登录</label><p class="form-error" role="alert" hidden></p><button class="primary auth-submit" type="submit">登录</button></form></section></div>`;const form=host.querySelector('form'),err=host.querySelector('.form-error');form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form),u=(d.get('username')||'').trim().toLowerCase(),p=d.get('password')||'';if(!/^[a-z0-9][a-z0-9_.-]{2,31}$/.test(u)){err.textContent='用户名请用 3—32 位英文字母、数字或 . _ -';err.hidden=false;return}if(p.length<10){err.textContent='密码至少 10 个字符';err.hidden=false;return}err.hidden=true;form.hidden=true;sandboxDone(host,'✓ 登录成功。你已经会登录了，继续下一步。')})}
function sandboxOverview(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>工作概览</h2><div class="sop-overview-stats">${[['0','待确认'],['1','进行中'],['2','待验收'],['1','已完成']].map(([n,t])=>`<div class="sop-stat"><b>${n}</b><span>${t}</span></div>`).join('')}</div><div class="sop-fake-tasks"><button type="button" class="sop-fake-task" data-sop-fake="1"><b>现场摄影与精修</b><small>迎新晚会拍摄 · 今天 18:00</small></button><button type="button" class="sop-fake-task" data-sop-fake="2"><b>推送文案初稿</b><small>迎新专题推送 · 明天 18:00</small></button></div><p class="sop-overview-detail" hidden></p></section></div>`;const detail=host.querySelector('.sop-overview-detail');host.querySelectorAll('[data-sop-fake]').forEach(el=>el.addEventListener('click',()=>{detail.hidden=false;detail.textContent=el.dataset.sopFake==='1'?'你点开了一个任务：负责人是你，截止今天 18:00，交付要求是精修 30 张并上传素材库。':'你点开了一个任务：负责人是你，截止明天 18:00，交付要求是完成文案初稿。';host.classList.add('done')}))}
function sandboxTask(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>现场摄影与精修</h2><p class="sub">迎新晚会拍摄 · 截止今天 18:00</p><h3>交付要求</h3><p>覆盖舞台、合影与花絮；精修 30 张并上传素材库。</p><div class="sop-task-checks">${['已上传原始文件到素材库','已交付精修图','已备注摄影署名'].map(c=>`<label class="check-line"><input type="checkbox">${c}</label>`).join('')}</div><div data-sop-stage-accept><button type="button" class="primary" data-sop-accept>接受任务</button></div><div data-sop-stage-submit hidden><label class="field">成果与交接说明<textarea data-sop-submit-text placeholder="完成了什么、文件在哪里、有哪些交接事项"></textarea></label><p class="form-error" hidden></p><button type="button" class="primary" data-sop-submit>提交给验收人</button></div></section></div>`;const accept=host.querySelector('[data-sop-stage-accept]'),submit=host.querySelector('[data-sop-stage-submit]');host.querySelector('[data-sop-accept]').addEventListener('click',()=>{accept.hidden=true;submit.hidden=false});host.querySelector('[data-sop-submit]').addEventListener('click',()=>{const text=host.querySelector('[data-sop-submit-text]').value.trim();const err=submit.querySelector('.form-error');if(!text){err.textContent='请写清成果在哪、交接给谁';err.hidden=false;return}submit.hidden=true;sandboxDone(host,'✓ 已提交，等待验收。')})}
function sandboxEvent(host){const day=localDay(),end=new Date(Date.now()+3*86400000);const endDay=`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,'0')}-${String(end.getDate()).padStart(2,'0')}`;host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>新建活动</h2><form novalidate><label class="field">活动名称<input name="name" required maxlength="60" placeholder="例如：迎新晚会拍摄"></label><div class="form-grid"><label class="field">开始日期<input name="date" type="date" value="${day}"></label><label class="field">结束日期<input name="endDate" type="date" value="${endDay}"></label></div><label class="check-line"><input type="checkbox" name="allDay" checked> 全天</label><label class="field">地点（可选）<input name="location" maxlength="100" placeholder="例如：主楼前广场"></label><label class="field">活动说明<textarea name="description" maxlength="3000" placeholder="安排、参与范围和期望成果"></textarea></label><label class="field">每项任务积分<input name="rewardPoints" type="number" min="0" max="10000" step="1" value="0"></label><p class="form-error" role="alert" hidden></p><button class="primary auth-submit" type="submit">创建日程</button></form></section></div>`;const form=host.querySelector('form'),err=host.querySelector('.form-error');form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form),name=(d.get('name')||'').trim(),date=d.get('date')||'',endDate=d.get('endDate')||'',location=(d.get('location')||'').trim(),description=(d.get('description')||'').trim(),points=Number(d.get('rewardPoints')||0);if(!name){err.textContent='请填写活动名称';err.hidden=false;return}if(date>endDate){err.textContent='结束日期不能早于开始日期';err.hidden=false;return}err.hidden=true;form.hidden=true;host.insertAdjacentHTML('beforeend',`<div class="sop-sandbox-ok">✓ 已创建日程「${esc(name)}」。</div><div class="sop-sandbox-result"><b>${esc(name)}</b><p>${esc(date)}${endDate&&endDate!==date?' — '+esc(endDate):''}${location?' · '+esc(location):''}</p><p class="sub">${esc(description||'（未填写说明）')} · 默认 ${points} 积分</p></div>`);host.classList.add('done')})}
function sandboxCalendar(host){const now=new Date(),y=now.getFullYear(),m=now.getMonth(),days=new Date(y,m+1,0).getDate(),first=(new Date(y,m,1).getDay()+6)%7,marked=new Set([3,12,20]);let cells='';for(let d=0;d<Math.ceil((first+days)/7)*7;d++){const day=d-first+1,inMonth=day>=1&&day<=days,isMarked=inMonth&&marked.has(day);cells+=`<button type="button" class="sop-cal-day ${inMonth?'':'muted'}" data-sop-day="${inMonth?day:''}" ${isMarked?'data-marked="1"':''}>${inMonth?day:''}${isMarked?'<i>•</i>':''}</button>`}host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>日历</h2><div class="sop-cal-head">${'一二三四五六日'.split('').map(w=>`<span>${w}</span>`).join('')}</div><div class="sop-cal-grid">${cells}</div><p class="sop-cal-detail" hidden></p></section></div>`;const detail=host.querySelector('.sop-cal-detail');host.querySelectorAll('[data-sop-day]').forEach(el=>el.addEventListener('click',()=>{const day=el.dataset.sopDay;if(!day)return;detail.hidden=false;detail.textContent=el.dataset.marked?`${day} 号有一个日程：迎新晚会拍摄 18:30。点活动方块能看详情。`:`${day} 号没有日程。`;host.classList.add('done')}))}
function sandboxProfile(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>个人资料</h2><div class="sop-profile-row"><div class="sop-profile-avatar" data-sop-avatar>头像</div><button type="button" class="secondary" data-sop-pick>选择图片</button><input type="file" accept="image/*" data-sop-file hidden></div><label class="field">姓名<input name="name" value="示例成员"></label><p class="hint">姓名和头像修改需要管理员审核。</p><button type="button" class="primary" data-sop-profile-save>提交审核</button></section></div>`;const file=host.querySelector('[data-sop-file]'),avatar=host.querySelector('[data-sop-avatar]');host.querySelector('[data-sop-pick]').addEventListener('click',()=>file.click());file.addEventListener('change',()=>{const f=file.files[0];if(!f)return;avatar.style.backgroundImage=`url(${URL.createObjectURL(f)})`;avatar.textContent=''});host.querySelector('[data-sop-profile-save]').addEventListener('click',()=>sandboxDone(host,'✓ 已提交，等待管理员审核。'))}
function sandboxAppearance(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card" data-sop-app-card><h2>外观设置</h2><div class="form-grid"><label class="field">语言<select data-sop-lang><option>中文</option><option>English</option></select></label><label class="field">字号<input type="range" min="85" max="135" value="100" data-sop-fontsize></label></div><label class="field">主题色<input type="color" value="#e77b24" data-sop-color></label><label class="field">外观<select data-sop-mode><option>白色</option><option>黑色</option><option>跟随系统</option></select></label><button type="button" class="primary" data-sop-app-save>保存并同步</button></section></div>`;const card=host.querySelector('[data-sop-app-card]');const apply=()=>{card.style.setProperty('--accent',host.querySelector('[data-sop-color]').value);card.style.fontSize=(Number(host.querySelector('[data-sop-fontsize]').value)/100)+'em';const dark=host.querySelector('[data-sop-mode]').value==='黑色';card.style.background=dark?'#1d1b19':'#fff';card.style.color=dark?'#f4f0ea':'#2b2724'};host.querySelectorAll('[data-sop-color],[data-sop-fontsize],[data-sop-mode]').forEach(el=>el.addEventListener('input',apply));host.querySelector('[data-sop-app-save]').addEventListener('click',()=>sandboxDone(host,'✓ 已保存，换设备登录会自动同步。'))}
function sandboxSafety(host){host.innerHTML=`<div class="sop-sandbox-wrap"><section class="sop-sandbox-card"><h2>本机安全中心</h2><p class="sub">检查和诊断只在本机进行，不上传任务、成员资料或触控位置。</p><button type="button" class="primary" data-sop-check>检查并修复</button><div class="sop-safety-result" hidden></div></section></div>`;host.querySelector('[data-sop-check]').addEventListener('click',()=>{const r=host.querySelector('.sop-safety-result');r.hidden=false;r.innerHTML='本机存储 可用<br>界面渲染 正常<br>画布 可用<br>版本 v1.0.7';host.classList.add('done')})}
function mountSandboxes(scope){for(const host of scope.querySelectorAll('.sop-sandbox[data-sandbox]')){const t=host.dataset.sandbox;({login:sandboxLogin,overview:sandboxOverview,task:sandboxTask,event:sandboxEvent,calendar:sandboxCalendar,profile:sandboxProfile,appearance:sandboxAppearance,safety:sandboxSafety}[t]||(()=>{}))(host)}}
function closeSopToPreview(){const mount=document.getElementById('sop-fullscreen');if(!mount)return;const idx=mount.dataset.sopIndex;mount.classList.remove('in');mount.classList.add('out');setTimeout(()=>{mount.remove();document.body.classList.remove('sop-locked');if(idx)openSop(Number(idx))},180)}
function openSop(index){const list=sopDocuments||[];if(!list.length)return;const idx=Math.min(Math.max(Number(index)-1,0),list.length-1);const d=list[idx];const body=sopMarkdown(d.content);$('#dialog-body').innerHTML=`<div class="modal-head"><h2>${esc(d.title)}</h2><div class="sop-preview-actions"><button type="button" class="secondary" data-sop-tour>边看边点</button><button type="button" class="primary" data-sop-full="${idx+1}">全屏阅读</button><button class="close" data-close aria-label="关闭">×</button></div></div><div class="modal-content"><p class="sub">${esc(d.path)}</p><div class="sop-reader">${body}</div><p id="form-error" class="form-error" role="alert"></p></div>`;if(!$('#dialog').open)$('#dialog').showModal();mountSandboxes(document.getElementById('dialog'))}
function closeSop(){document.getElementById('sop-fullscreen')?.remove();document.body.classList.remove('sop-locked')}
function openSopFull(index){const list=sopDocuments||[];if(!list.length)return;const current=Math.min(Math.max(Number(index)-1,0),list.length-1);closeSop();const mount=document.createElement('div');mount.className='sop-fullscreen';mount.id='sop-fullscreen';mount.setAttribute('role','dialog');mount.setAttribute('aria-modal','true');mount.dataset.sopIndex=String(current+1);
 const renderDoc=()=>{const d=list[current];const body=sopMarkdown(d.content);const total=(body.match(/data-sop-check/g)||[]).length;
  mount.innerHTML=`<div class="sop-full-top"><button type="button" class="secondary" data-sop-full-close aria-label="退出全屏阅读">← 返回知识库</button><div class="sop-full-title"><b>${esc(d.title)}</b><small>${esc(d.path)}</small></div><div class="sop-full-tools">${total?`<span class="sop-progress-inline"><b data-sop-progress-label>0 / ${total}</b><i data-sop-progress-fill></i></span><button type="button" class="text-btn" data-sop-reset>重置进度</button>`:''}<button type="button" class="text-btn" data-sop-font="-1" aria-label="缩小字号">A−</button><button type="button" class="text-btn" data-sop-font="1" aria-label="放大字号">A+</button><button type="button" class="primary" data-sop-tour>边看边点</button></div></div><div class="sop-full-layout"><aside class="sop-full-side"><div class="sop-full-docs-title">文档</div><div class="sop-full-docs">${list.map((x,i)=>`<button type="button" class="sop-doc-nav ${i===current?'active':''}" data-sop-doc-index="${i+1}">${esc(x.title)}</button>`).join('')}</div><div class="sop-full-toc" data-sop-toc></div></aside><div class="sop-full-content"><div class="sop-reader">${body}</div></div></div>`;
  const headings=[...(mount.querySelectorAll('.sop-reader h1, .sop-reader h2, .sop-reader h3')||[])];headings.forEach((h,i)=>{if(!h.id)h.id='sop-sec-'+(i+1)});const toc=mount.querySelector('[data-sop-toc]');if(toc&&headings.length)toc.innerHTML=`<div class="sop-full-toc-title">目录</div>${headings.map(h=>`<button type="button" class="sop-toc-link ${h.tagName==='H3'?'sub':''}" data-sop-toc-goto="${h.id}">${esc(h.textContent)}</button>`).join('')}`;
  if(total)sopChecklistInit(mount,d.path);mountSandboxes(mount);applySopFont(mount)};
 renderDoc();document.body.append(mount);document.body.classList.add('sop-locked');requestAnimationFrame(()=>requestAnimationFrame(()=>mount.classList.add('in')))}
document.addEventListener('click',e=>{
 if(e.target.closest?.('[data-sop-full-close]')){closeSopToPreview();return}
 const full=e.target.closest?.('[data-sop-full]');if(full){if($('#dialog')?.open)$('#dialog').close();openSopFull(Number(full.dataset.sopFull));return}
 const dn=e.target.closest?.('[data-sop-doc-index]');if(dn){openSopFull(Number(dn.dataset.sopDocIndex));return}
 const fs=e.target.closest?.('[data-sop-font]');if(fs){adjustSopFont(Number(fs.dataset.sopFont));return}
 const tg=e.target.closest?.('[data-sop-toc-goto]');if(tg){document.getElementById(tg.dataset.sopTocGoto)?.scrollIntoView({behavior:'smooth',block:'start'});return}
 const tr=e.target.closest?.('[data-sop-tour]');if(tr){if($('#dialog')?.open)$('#dialog').close();closeSop();startTour();return}
 const j=e.target.closest?.('[data-sop-nav]');if(j){e.preventDefault();if($('#dialog')?.open)$('#dialog').close();closeSop();view=j.dataset.sopNav;render();return}
});

let tour=null,tourChecked=false;
function tourSeen(){try{return localStorage.getItem(SOP_SEEN_KEY)==='1'}catch{return false}}
function markTourSeen(){try{localStorage.setItem(SOP_SEEN_KEY,'1')}catch{}}
function tourSteps(){return[
 {view:'overview',sel:'nav a[data-view="overview"]',title:'这是导航栏',body:'左边这些入口用来切换页面。点一下试试，或点「下一步」继续。'},
 {view:'tasks',sel:'main [data-task], nav a[data-view="tasks"]',title:'你的任务在这里',body:'你负责或验收的任务都在这。点开一个任务能看到截止时间、交付要求和验收人。'},
 {view:'calendar',sel:'.calendar, nav a[data-view="calendar"]',title:'日历和排期',body:'活动日期和任务截止时间都在这。下面还有能左右拖动的时间轴。'},
 {view:'overview',sel:'[data-profile], .account-dock [data-account]',title:'个人资料与设置',body:'点你的名字能改头像、资料、密码，也能打开设置。'},
 {view:'sop',sel:'.sop-document, nav a[data-view="sop"]',title:'知识库',body:'手册、规范都在这。点开《新手快速入门》可以边看边做。'}
]}
function stopTour(){tour=null;document.querySelectorAll('.tour-target').forEach(el=>el.classList.remove('tour-target'));document.getElementById('tour-tip')?.remove()}
function nextTour(){if(!tour)return;tour.index++;showTourStep()}
function prevTour(){if(!tour)return;tour.index=Math.max(0,tour.index-1);showTourStep()}
function startTour(){if(!user||user.status!=='active')return;tour={index:0};showTourStep()}
function showTourStep(){const steps=tourSteps();if(!tour||tour.index>=steps.length){markTourSeen();stopTour();return}const step=steps[tour.index];if($('#dialog')?.open)$('#dialog').close();if(step.view&&view!==step.view){view=step.view;render()}document.querySelectorAll('.tour-target').forEach(el=>el.classList.remove('tour-target'));let target=step.sel?document.querySelector(step.sel):null;if(!target)target=document.querySelector('main')||document.body;target.classList.add('tour-target');target.scrollIntoView({behavior:'smooth',block:'center'});let tip=document.getElementById('tour-tip');if(!tip){tip=document.createElement('div');tip.id='tour-tip';tip.setAttribute('role','dialog');document.body.append(tip)}const dots=steps.map((s,i)=>`<i class="${i===tour.index?'on':i<tour.index?'done':''}"></i>`).join('');tip.innerHTML=`<button type="button" class="tour-close" data-tour-close aria-label="关闭引导">×</button><span class="tour-stepno">第 ${tour.index+1} / ${steps.length} 步</span><h3>${esc(step.title)}</h3><p>${esc(step.body)}</p><div class="tour-dots">${dots}</div><div class="tour-actions">${tour.index>0?'<button type="button" class="secondary" data-tour-prev>上一步</button>':''}<button type="button" class="text-btn" data-tour-skip>跳过</button><button type="button" class="primary" data-tour-next>${tour.index===steps.length-1?'完成':'下一步'}</button></div>`;positionTourTip(tip,target)}
function positionTourTip(tip,target){const r=target.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(window.innerWidth-tip.offsetWidth-12,r.left+r.width/2-tip.offsetWidth/2))+'px';const below=r.bottom+12;if(below+tip.offsetHeight<window.innerHeight-12)tip.style.top=below+'px';else tip.style.top=Math.max(12,r.top-tip.offsetHeight-12)+'px'}
function maybeStartTour(){if(tourChecked||tour||!user||user.status!=='active')return;tourChecked=true;if(tourSeen())return;setTimeout(()=>{if(!tour&&!document.getElementById('sop-fullscreen')&&document.querySelector('nav'))startTour()},900)}
document.addEventListener('click',e=>{
 if(e.target.closest?.('[data-tour-close]')){markTourSeen();stopTour();return}
 if(e.target.closest?.('[data-tour-skip]')){markTourSeen();stopTour();return}
 if(e.target.closest?.('[data-tour-next]')){if(tour&&tour.index===tourSteps().length-1)markTourSeen();nextTour();return}
 if(e.target.closest?.('[data-tour-prev]')){prevTour();return}
},true);

document.addEventListener('pointerover',e=>{const summary=e.target.closest('.check-help summary');if(summary&&e.pointerType==='mouse'&&!summary.parentElement.open){summary.parentElement.open=true;summary.parentElement.dataset.hoverOpen='1'}});
document.addEventListener('pointerout',e=>{const help=e.target.closest('.check-help');if(help&&help.dataset.hoverOpen&&!help.contains(e.relatedTarget)){help.open=false;delete help.dataset.hoverOpen}});
document.addEventListener('click',e=>{const summary=e.target.closest('.check-help summary');if(summary&&(summary.parentElement.dataset.hoverOpen||summary.parentElement.dataset.longOpen)){e.preventDefault();delete summary.parentElement.dataset.hoverOpen;delete summary.parentElement.dataset.longOpen;summary.parentElement.open=true}});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.name==='template'&&el.form?.id==='create-form')renderAssignments();
  if(el.name==='allDay')el.form.querySelector('.time-fields').hidden=el.checked;
  if(el.name==='date'&&el.form?.elements.endDate&&el.form.elements.endDate.value<el.value)el.form.elements.endDate.value=el.value;
  if(el.matches('[data-calendar-dept]')){calendarDept=el.value;render()}
});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-timeline-scale]')){const scroller=$('.time-scroll'),ratio=Number(el.value)/timelineScale,scroll=scroller.scrollLeft,canvas=$('.time-canvas');timelineScale=Number(el.value);canvas.style.width=(new Date(year,month+1,0).getDate()*timelineScale)+'px';canvas.style.setProperty('--day-width',timelineScale+'px');canvas.querySelectorAll('.time-date').forEach(x=>x.style.width=timelineScale+'px');canvas.querySelectorAll('.time-bar').forEach(x=>{x.style.left=((parseFloat(x.style.left)-3)*ratio+3)+'px';x.style.width=((parseFloat(x.style.width)+6)*ratio-6)+'px'});scroller.scrollLeft=scroll*ratio;}
  if(el.name==='link'&&el.form?.id==='submit-form'){const box=el.form.querySelector('.personal-link-confirm'),check=el.form.elements.linkConfirmed;box.hidden=!el.value.trim();check.required=!!el.value.trim();check.checked=false;}
});
document.addEventListener('click',async e=>{const a=e.target.closest('button,a');if(!a)return;try{
  if(a.hasAttribute('data-open-upload')){const check=$('#submit-form [name=uploadConfirmed]');check.disabled=false;}
  if(a.hasAttribute('data-copy-url')){await navigator.clipboard.writeText(a.dataset.copyUrl);toast('链接已复制');}
  if(a.hasAttribute('data-preview-link')){const input=$('#submit-form [name=link]');if(!input.value||!input.checkValidity())throw Error('请先填写有效的成果链接');const url=new URL(input.value);if(!['https:','http:'].includes(url.protocol))throw Error('请使用 http 或 https 链接');window.open(url.href,'_blank','noopener,noreferrer');}
  if(a.hasAttribute('data-add-step')){const list=$('#template-steps');if(list.children.length>=30)throw Error('最多 30 个环节');list.insertAdjacentHTML('beforeend',stepEditor({},list.children.length));}
  if(a.hasAttribute('data-remove-step')){const list=$('#template-steps'),row=a.closest('.template-step'),index=[...list.children].indexOf(row);row.remove();[...list.children].forEach((el,i)=>{el.querySelector('.step-index').textContent=i+1;const dep=el.querySelector('[data-key=depends]');dep.value=dep.value.split(/[,，]/).map(v=>Number(v.trim())).filter(v=>v>0&&v!==index+1).map(v=>v>index+1?v-1:v).join(',')});}
  if(a.hasAttribute('data-today')){year=new Date().getFullYear();month=new Date().getMonth();selectedDay=localDay();render();$('.time-scroll')?.scrollTo({left:(new Date().getDate()-2)*timelineScale,behavior:'smooth'});}
  if(a.dataset.selectDay){selectedDay=a.dataset.selectDay;render();}
}catch(err){toast(err.message)}});

// Mouse drag-to-pan; touch uses native scrolling. Event handles work with mouse and touch.
let timelineDrag=null,pan=null,suppressTimelineClick=false,longPressTimer,longPressOrigin=null;
document.addEventListener('pointerdown',e=>{
  const help=e.target.closest('.check-help summary');if(help&&e.pointerType==='touch'){longPressOrigin={x:e.clientX,y:e.clientY};longPressTimer=setTimeout(()=>{help.parentElement.open=true;help.parentElement.dataset.longOpen='1'},450);}
  const handle=e.target.closest('[data-drag-event]');if(handle){timelineDrag={id:handle.dataset.dragEvent,startX:e.clientX,delta:0,handle};handle.setPointerCapture(e.pointerId);e.preventDefault();return;}
  const scroller=e.target.closest('.time-scroll');if(scroller&&e.pointerType==='mouse'&&!e.target.closest('button')){pan={el:scroller,x:e.clientX,left:scroller.scrollLeft};scroller.setPointerCapture(e.pointerId)}
});
document.addEventListener('pointermove',e=>{if(longPressOrigin&&Math.hypot(e.clientX-longPressOrigin.x,e.clientY-longPressOrigin.y)>12){clearTimeout(longPressTimer);longPressOrigin=null}if(timelineDrag){const d=timelineDrag;d.delta=Math.round((e.clientX-d.startX)/timelineScale);d.handle.closest('.time-bar').style.transform=`translateX(${d.delta*timelineScale}px)`}if(pan)pan.el.scrollLeft=pan.left+pan.x-e.clientX;});
function endPointer(e,cancel=false){clearTimeout(longPressTimer);pan=null;if(!timelineDrag)return;const d=timelineDrag;timelineDrag=null;d.handle.closest('.time-bar').style.transform='';if(cancel||!d.delta)return;const event=state.events.find(x=>x.id===d.id);const date=dayShift(event.date,d.delta);suppressTimelineClick=true;setTimeout(()=>suppressTimelineClick=false,300);modal('确认活动改期',`<form id="date-form" data-id="${event.id}"><p>${esc(event.name)}</p><label class="field">新的开始日期<input name="date" type="date" value="${date}" required></label><div class="hint">未完成任务与活动结束日期同步平移 ${d.delta} 天，已完成记录和积分保持不变。</div></form>`,`<button class="primary" form="date-form" type="submit">确认并同步日历</button>`)}
document.addEventListener('pointerup',e=>endPointer(e));
document.addEventListener('pointercancel',e=>endPointer(e,true));
document.addEventListener('click',e=>{if(suppressTimelineClick&&e.target.closest('.time-scroll')){e.stopImmediatePropagation();e.preventDefault()}},true);
